import java.io.*;
import java.util.*;

public class CF884F_Variant1 extends PrintWriter {
    static final int ALPH = 26;
    static final int INF = 0x3f3f3f3f;

    int[] next, edgeTo;
    int ptr = 1;
    int[] from, to, cap, weight, redWeight;
    int edges;
    int[] first, dist, hops, prevEdge;
    int vertices;
    int[] heap, heapPos;
    int heapSize;

    CF884F_Variant1() { super(System.out, true); }
    Scanner in = new Scanner(System.in);

    public static void main(String[] args) {
        CF884F_Variant1 solver = new CF884F_Variant1();
        solver.run();
        solver.flush();
    }

    int addToList(int head, int edge) {
        next[ptr] = head;
        edgeTo[ptr] = edge;
        return ptr++;
    }

    void init() {
        next = new int[1 + edges * 2];
        edgeTo = new int[1 + edges * 2];
        from = new int[edges];
        to = new int[edges];
        cap = new int[edges << 1];
        weight = new int[edges];
        redWeight = new int[edges];
        first = new int[vertices];
        dist = new int[vertices];
        hops = new int[vertices];
        prevEdge = new int[vertices];
        heap = new int[vertices + 1];
        heapPos = new int[vertices];
        edges = 0;
    }

    void addEdge(int u, int v, int c, int w) {
        int e = edges++;
        from[e] = u;
        to[e] = v;
        cap[e << 1] = c;
        weight[e] = w;
        first[u] = addToList(first[u], e << 1);
        first[v] = addToList(first[v], e << 1 | 1);
    }

    boolean less(int u, int v) {
        return dist[u] < dist[v] || (dist[u] == dist[v] && hops[u] < hops[v]);
    }

    int child(int i) {
        i <<= 1;
        if (i > heapSize) return 0;
        if (i < heapSize && less(heap[i + 1], heap[i])) i++;
        return i;
    }

    void heapUp(int u) {
        int i, j, v;
        for (i = heapPos[u]; (j = i >> 1) > 0 && less(u, v = heap[j]); i = j)
            heap[heapPos[v] = i] = v;
        heap[heapPos[u] = i] = u;
    }

    void heapDown(int u) {
        int i, j, v;
        for (i = heapPos[u]; (j = child(i)) > 0 && less(v = heap[j], u); i = j)
            heap[heapPos[v] = i] = v;
        heap[heapPos[u] = i] = u;
    }

    void addToHeap(int u) {
        heap[heapPos[u] = ++heapSize] = u;
    }

    int removeMin() {
        int u = heap[1], v = heap[heapSize--];
        if (v != u) {
            heapPos[v] = 1;
            heapDown(v);
        }
        heapPos[u] = 0;
        return u;
    }

    boolean dijkstra(int s, int t) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        addToHeap(s);
        while (heapSize > 0) {
            int u = removeMin();
            int nh = hops[u] + 1;
            for (int p = first[u]; p != 0; p = next[p]) {
                int arc = edgeTo[p];
                if (cap[arc] > 0) {
                    int e = arc >> 1;
                    int v = u ^ from[e] ^ to[e];
                    int nd = dist[u] + ((arc & 1) == 0 ? redWeight[e] : -redWeight[e]);
                    if (dist[v] > nd || (dist[v] == nd && hops[v] > nh)) {
                        if (dist[v] == INF) addToHeap(v);
                        dist[v] = nd;
                        hops[v] = nh;
                        prevEdge[v] = arc;
                        heapUp(v);
                    }
                }
            }
        }
        return dist[t] != INF;
    }

    int augment(int s, int t) {
        while (t != s) {
            int arc = prevEdge[t], e = arc >> 1;
            cap[arc]--;
            cap[arc ^ 1]++;
            t ^= from[e] ^ to[e];
        }
        return 1;
    }

    int minCostFlow(int s, int t) {
        for (int e = 0; e < edges; e++) {
            int u = from[e], v = to[e];
            dist[v] = Math.min(dist[v], dist[u] + weight[e]);
        }
        for (int e = 0; e < edges; e++) {
            int u = from[e], v = to[e];
            redWeight[e] = weight[e] + dist[u] - dist[v];
        }
        while (dijkstra(s, t)) {
            augment(s, t);
            for (int e = 0; e < edges; e++) {
                int u = from[e], v = to[e];
                if (dist[u] != INF && dist[v] != INF) {
                    redWeight[e] += dist[u] - dist[v];
                }
            }
        }
        int cost = 0;
        for (int e = 0; e < edges; e++)
            cost += weight[e] * cap[e << 1 | 1];
        return cost;
    }

    void run() {
        int n = in.nextInt() / 2;
        vertices = 1 + n + ALPH + 1;
        edges = n + n * ALPH + ALPH;
        init();
        byte[] s = in.next().getBytes();
        int[] b = new int[2 * n];
        for (int i = 0; i < 2 * n; i++) b[i] = in.nextInt();
        for (int i = 0; i < n; i++) addEdge(0, 1 + i, 2, 0);
        for (int i = 0; i < n; i++) {
            int j = 2 * n - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < ALPH; a++) {
                int val;
                if (a == ai && a == aj) val = Math.max(b[i], b[j]);
                else if (a == ai) val = b[i];
                else if (a == aj) val = b[j];
                else val = 0;
                addEdge(1 + i, 1 + n + a, 1, -val);
            }
        }
        int[] cnt = new int[ALPH];
        for (int i = 0; i < 2 * n; i++) cnt[s[i] - 'a']++;
        for (int a = 0; a < ALPH; a++) addEdge(1 + n + a, vertices - 1, cnt[a], 0);
        println(-minCostFlow(0, vertices - 1));
    }
}
